use super::*;
use self::core::wire::Capability;
use std::sync::Arc;
fn id()->String{uuid::Uuid::new_v4().to_string()}
fn fixture(n:&str)->Vec<u8>{fs::read(Path::new(env!("CARGO_MANIFEST_DIR")).join("../docs/evidence/5d3b1/fixtures").join(format!("{n}.json"))).unwrap()}
struct Qa{root:PathBuf,repo:Repository}
impl Qa{fn new()->Self{let root=std::env::temp_dir().join("opencode").join(format!("4c-repository-{}",id()));let repo=Repository::new(root.clone(),Policy::qa()).execution_test_clock(Clock{fixed:Some(Arc::new(Mutex::new("2026-10-26T12:00:00Z".into())))});repo.initialize_new().unwrap();repo.accept_trust_episode(&id(),0,&[fixture("trust1")]).unwrap();Self{root,repo}}
fn install_select(&self,n:&str){let g=self.repo.open_existing().unwrap().generation;let iid=self.repo.record_verified_installation(&id(),g,&fixture(n),&[Capability::Direct,Capability::Inverse]).unwrap().installation_id.unwrap();let p=self.repo.prepare_activation(ActivationIntent::Admit,Some(&iid),None,None).unwrap();self.repo.confirm_activation(&id(),&p).unwrap();let p=self.repo.prepare_activation(ActivationIntent::Select,Some(&iid),p.admission_id.as_deref(),None).unwrap();self.repo.confirm_activation(&id(),&p).unwrap();}
fn material(&self)->execution::ExecutionMaterial{let s=self.repo.selection_status().unwrap().selection;self.repo.prepare_execution(&s,"2026-02-01","monthly","gross-to-net").unwrap()}}
impl Drop for Qa{fn drop(&mut self){let _=fs::remove_dir_all(&self.root);}}
#[test]fn signed_floor_or_epoch_invalidates_issued_execution_without_replacing_context(){for update in ["floor2","epoch2"]{let q=Qa::new();q.install_select("package1");let material=q.material();let g=q.repo.open_existing().unwrap().generation;q.repo.accept_trust_episode(&id(),g,&[fixture(update)]).unwrap();assert!(q.repo.revalidate_execution(&material.context).is_err());assert_eq!(material.context.revision,1);assert_eq!(material.context.epoch,1);}}
#[test]fn unrelated_withdrawal_cannot_be_hidden_behind_an_old_documentable_head(){let q=Qa::new();q.install_select("package1");q.install_select("package2");let m=q.material();let hash=m.context.trust_head_sha256.clone();let g=q.repo.open_existing().unwrap().generation;q.repo.accept_trust_episode(&id(),g,&[fixture("withdrawn")]).unwrap();let e=q.repo.revalidate_execution(&m.context).unwrap_err();assert_eq!(e.code,"MATERIAL_NOT_DOCUMENTABLE");assert_eq!(m.context.trust_head_sha256,hash);let selected=q.repo.selection_status().unwrap().selection;assert_eq!(q.repo.prepare_execution(&selected,"2026-02-01","monthly","gross-to-net").err().unwrap().code,"MATERIAL_NOT_DOCUMENTABLE");}
